package io.lumine.mythic.lib.api.util.ui;
public abstract class FriendlyFeedbackPalette {
 public abstract String getBodyFormat(); public abstract String consoleBodyFormat(); public abstract String getExampleFormat(); public abstract String consoleExampleFormat(); public abstract String getInputFormat(); public abstract String consoleInputFormat(); public abstract String getResultFormat(); public abstract String consoleResultFormat(); public abstract String getSuccessFormat(); public abstract String consoleSuccessFormat(); public abstract String getFailureFormat(); public abstract String consoleFailureFormat(); public abstract String getRawPrefix(); public abstract String getRawPrefixConsole(); public abstract String getSubdivisionFormat(); public abstract String consoleSubdivisionFormat();
 String getPrefix(String s){return getRawPrefix().replace("#s",s==null?"":" "+getSubdivisionFormat()+s);} String consolePrefix(String s){return getRawPrefixConsole().replace("#s",s==null?"":" "+consoleSubdivisionFormat()+s);}
 public String parseForPlayer(String m){return m.replace("$b",getBodyFormat()).replace("$e",getExampleFormat()).replace("$i",getInputFormat()).replace("$u",getInputFormat()).replace("$s",getSuccessFormat()).replace("$f",getFailureFormat()).replace("$r",getResultFormat());}
 public String parseForConsole(String m){return m.replace("$b",consoleBodyFormat()).replace("$e",consoleExampleFormat()).replace("$i",consoleInputFormat()).replace("$u",consoleInputFormat()).replace("$s",consoleSuccessFormat()).replace("$f",consoleFailureFormat()).replace("$r",consoleResultFormat());}
}
